// Run with a Playwright page; uses an isolated browser context and only demo data.
async (page) => {
  const ctx = await page.context().browser().newContext({ viewport: { width: 390, height: 844 } });
  const p = await ctx.newPage();
  const failures = [], checks = [], errors = [], requests = [];
  const key = 'daily-checkin:prototype:v1';
  const assert = (condition, message) => { if (!condition) throw new Error(message); checks.push(message); };
  const data = () => p.evaluate(k => JSON.parse(localStorage.getItem(k)), key);
  const visit = async route => { await p.goto(`http://127.0.0.1:18093/#${route}`); await p.waitForSelector('main h1, main h2'); };
  const hash = async value => p.waitForFunction(v => v === '#/add/done' || v.endsWith('?') ? location.hash.startsWith(v) : location.hash === v, value);
  const submit = name => p.getByRole('button', { name, exact: true }).click();
  p.on('pageerror', e => errors.push(e.message));
  p.on('request', r => { if (!r.url().startsWith('http://127.0.0.1:18093/') && !r.url().startsWith('data:')) requests.push(r.url()); });
  try {
    await visit('/home');
    assert((await p.locator('.hero-value').innerText()).replace(/\s/g, '') === '2/4', '首页按开启的账号计算 2/4');
    assert(await p.locator('.run-row').count() === 5, '首页仅显示最近五条记录');
    await visit('/accounts');
    assert(await p.locator('.account-card').count() === 5, '预置三个 App、两个小程序账号');
    const before = await data();
    await p.getByRole('switch', { name: '龙湖 App 家人号 自动签到' }).click();
    assert((await data()).accounts.find(a => a.id === 'app-family').enabled === false, '单账号开关生效');
    assert(JSON.stringify((await data()).accounts.find(a => a.id === 'app-main')) === JSON.stringify(before.accounts.find(a => a.id === 'app-main')), '切换第二个 App 不影响主号');
    await p.getByRole('switch', { name: '龙湖 App 家人号 自动签到' }).click();
    await p.getByRole('link', { name: '添加账号', exact: true }).click();
    await p.locator('[data-action="choose-program"][data-id="longfor_app"]').click();
    await p.locator('#alias').fill('第二个 App · 测试');
    await p.locator('select[name=sample]').selectOption('missing');
    await submit('导入并校验');
    await p.locator('.form-error').waitFor();
    assert(await p.locator('.form-error').innerText().then(t => t.includes('成功登录响应')), '导入缺少登录响应时有具体错误');
    assert((await data()).accounts.length === 5, '校验失败不创建账号');
    await p.locator('select[name=sample]').selectOption('valid');
    await submit('导入并校验');
    await hash('#/add/verified');
    await p.getByRole('link', { name: '设置签到计划' }).click();
    assert(await p.locator('input[name=enabled]').isChecked() === false, '新账号需要主动确认开启计划');
    await p.locator('input[name=signTime]').fill('08:30');
    await p.locator('input[name=checkTime]').fill('08:20');
    await submit('完成添加');
    assert(await p.locator('.form-error').innerText().then(t => t.includes('之后')), '复核必须晚于签到');
    await p.locator('input[name=checkTime]').fill('16:30');
    await p.locator('input[name=enabled]').check();
    await submit('完成添加');
    await hash('#/add/done');
    let current = await data();
    const added = current.accounts.find(a => a.alias === '第二个 App · 测试');
    assert(current.accounts.length === 6 && !!added && added.id !== 'app-main', '同一程序可重复添加且生成独立实例编号');
    assert(added.enabled && added.signTime === '08:30' && added.checkTime === '16:30', '新账号保存独立时间和开关');
    assert(JSON.stringify(current.accounts.find(a => a.id === 'app-main')) === JSON.stringify(before.accounts.find(a => a.id === 'app-main')), '添加账号不覆盖原 App 配置');
    await p.getByRole('link', { name: '查看账号', exact: true }).click();
    await p.getByRole('link', { name: /修改配置/ }).click();
    assert(await p.locator('#alias').inputValue() === added.alias, '修改页预填已有昵称');
    assert(await p.locator('input[name=signTime]').inputValue() === '08:30', '修改页预填已有签到时间');
    await p.locator('#alias').fill('家人备用 App');
    await p.locator('input[name=signTime]').fill('10:05');
    await submit('保存修改');
    await hash(`#/account/${added.id}`);
    await visit(`/account/${added.id}/auth`);
    const oldCred = (await data()).accounts.find(a => a.id === added.id).credentialUpdatedAt;
    await p.locator('select[name=sample]').selectOption('expired');
    await submit('校验并更新登录');
    await p.locator('.form-error').waitFor();
    assert((await data()).accounts.find(a => a.id === added.id).credentialUpdatedAt === oldCred, '失败更新保留原登录配置');
    await p.getByRole('button', { name: '短信更新', exact: true }).click();
    await p.locator('#sms-code').fill('123456');
    await submit('校验并更新登录');
    assert(await p.locator('.form-error').innerText().then(t => t.includes('先获取')), '短信更新先获取演示验证码');
    await submit('获取演示验证码');
    await submit('校验并更新登录');
    await hash(`#/account/${added.id}`);
    current = await data();
    assert(current.accounts.find(a => a.id === added.id).credentialUpdatedAt !== oldCred, 'App 短信更新演示完整可用');
    assert(current.accounts.find(a => a.id === added.id).signTime === '10:05', '登录更新保留账号计划');
    await p.locator('.demo-select summary').click();
    await p.locator('#scenario-select').selectOption('failed');
    await submit('立即签到');
    await p.waitForFunction(k => JSON.parse(localStorage.getItem(k)).runs[0].state === 'failed', key);
    assert((await data()).runs[0].accountId === added.id, '失败结果绑定当前实例');
    assert((await p.locator('main').innerText()).includes('签到提交失败'), '提交失败与确认未签到分别说明');
    await p.locator('.demo-select summary').click();
    await p.locator('#scenario-select').selectOption('success');
    await submit('立即签到');
    await p.waitForFunction(k => JSON.parse(localStorage.getItem(k)).runs[0].state === 'signed', key);
    assert(await p.getByRole('button', { name: '立即签到', exact: true }).count() === 0, '已确认签到后不再显示立即签到');
    await p.getByRole('link', { name: '查看今日结果', exact: true }).click();
    await hash('#/records?');
    assert(await p.locator('.run-row').count() === 1, '今日结果按当前账号、日期和成功状态筛选');
    await visit('/account/mini-main/auth');
    assert(await p.getByRole('button', { name: '短信更新', exact: true }).count() === 0, '小程序不展示未支持的短信登录');
    await visit('/account/app-family/auth');
    await submit('校验并更新登录');
    await hash('#/account/app-family');
    assert((await data()).accounts.find(a => a.id === 'app-family').authState === 'valid', '失效 App 可通过导入恢复');
    await visit('/notifications/wecom');
    await submit('模拟完成绑定');
    assert((await data()).notifications.wecom.bound, '企业微信绑定演示生效');
    await visit('/notifications/email');
    await p.locator('[name=provider]').selectOption('163');
    await p.locator('[name=address]').fill('demo@qq.com');
    await submit('保存邮箱配置');
    assert(await p.locator('.form-error').innerText().then(t => t.includes('@163.com')), '邮箱类型与地址必须一致');
    await p.locator('[name=address]').fill('demo@163.com');
    await submit('保存邮箱配置');
    await hash('#/notifications');
    assert((await data()).notifications.email.address === 'demo@163.com', '163 邮箱配置保存成功');
    await p.locator('.demo-tools summary').click();
    await p.locator('#simulate-notify-failure').check();
    await visit('/account/mini-family');
    await submit('立即签到');
    await p.waitForFunction(k => JSON.parse(localStorage.getItem(k)).runs[0].accountId === 'mini-family', key);
    const failedRun = (await data()).runs[0];
    assert(failedRun.state === 'signed' && failedRun.notification.state === 'failed', '通知失败不改变签到成功结果');
    await visit(`/run/${failedRun.id}`);
    await submit('重试演示通知');
    await p.waitForFunction(k => JSON.parse(localStorage.getItem(k)).runs[0].notification.attempts === 2, key);
    assert((await data()).runs[0].notification.state === 'failed', '失败场景持续时重试仍如实显示失败');
    await visit('/notifications');
    await p.locator('.demo-tools summary').click();
    await p.locator('#simulate-notify-failure').uncheck();
    await visit(`/run/${failedRun.id}`);
    await submit('重试演示通知');
    await p.waitForFunction(k => JSON.parse(localStorage.getItem(k)).runs[0].notification.state === 'sent', key);
    assert((await data()).runs[0].notification.attempts === 3, '通知恢复后重试成功并累计次数');
    await visit('/accounts');
    await p.locator('#account-search').fill('家人备用');
    assert(await p.locator('.account-card').count() === 1, '账号昵称搜索定位单个实例');
    await p.locator('#account-search').fill('');
    await p.locator('[data-action=filter-program][data-id=longfor_mini]').click();
    assert(await p.locator('.account-card').count() === 2, '程序筛选隔离 App 和小程序');
    await visit(`/account/${added.id}`);
    await submit('移除此账号');
    await submit('确认移除');
    await hash('#/accounts');
    current=await data();
    assert(!current.accounts.some(a=>a.id===added.id) && current.runs.some(r=>r.accountId===added.id), '移除账号保留历史记录');
    await visit(`/records?account=${added.id}`);
    assert(await p.locator('.run-row').count() === 2, '已移除账号仍可筛选历史记录');
    await visit('/about');
    await submit('重置演示数据');
    await submit('恢复默认');
    await hash('#/home');
    assert((await data()).accounts.length === 5, '默认演示可恢复');
    await visit('/me');
    await p.locator('.demo-tools summary').click();
    await submit('体验首次使用（空数据）');
    await submit('清空演示');
    await hash('#/home');
    assert((await data()).accounts.length === 0, '首次使用空状态完整可用');
    assert(await p.getByRole('heading',{name:'还没有签到账号'}).isVisible(), '空首页有明确添加引导');
    await visit('/about');
    await submit('重置演示数据');
    await submit('恢复默认');
    await hash('#/home');
    const routes=['/home','/accounts','/records','/me','/account/app-main','/account/app-main/edit','/account/app-family/auth','/account/mini-main/auth','/notifications','/notifications/email','/notifications/wecom','/help','/video','/about','/add/program','/run/run-1'];
    for(const width of [320,375,390,430,768,1440]) {
      await p.setViewportSize({width,height:844});
      for(const route of routes) {
        await visit(route);
        const dimensions=await p.evaluate(()=>({body:document.documentElement.scrollWidth,viewport:innerWidth}));
        if(dimensions.body>dimensions.viewport)failures.push({width,route,...dimensions});
      }
      await visit('/add/program');
      await p.locator('[data-action=choose-program][data-id=longfor_app]').click();
      if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth))failures.push({width,route:'/add/bind'});
      await submit('导入并校验');await hash('#/add/verified');
      await p.getByRole('link',{name:'设置签到计划'}).click();
      if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth))failures.push({width,route:'/add/plan'});
    }
    assert(failures.length===0,'320 / 375 / 390 / 430 / 768 / 1440px 全部页面无横向溢出：'+JSON.stringify(failures));
    await p.setViewportSize({width:390,height:844});
    await visit('/home');
    await p.screenshot({path:'/tmp/checkin-prototype-home.png',fullPage:true});
    await visit('/accounts');
    await p.screenshot({path:'/tmp/checkin-prototype-accounts.png',fullPage:true});
    await visit('/account/app-main');
    await p.screenshot({path:'/tmp/checkin-prototype-detail.png',fullPage:true});
    await p.setViewportSize({width:1440,height:1000});await visit('/home');
    await p.screenshot({path:'/tmp/checkin-prototype-desktop.png',fullPage:true});
    assert(errors.length===0,'无浏览器脚本异常：'+JSON.stringify(errors));
    assert(requests.length===0,'所有交互仅请求本地静态资源：'+JSON.stringify(requests));
    return {passed:checks.length,checks,failures,errors,externalRequests:requests};
  } finally { await ctx.close(); }
}
